What is the output of the following C program, assuming `strcpy` is defined as shown below?
```c
#include <stdio.h>
#include <string.h>
void strcpy_custom(char *dst, char *src)
{
    while(*src) *dst++ = *src++;
    *dst = '\0'; // Null-terminate the destination string
}

int main()
{
    char *src = "Hello World";
    char dst[100];
    strcpy_custom(dst, src);
    printf("%s",dst);
    return 0;
}
```

